'use strict';
const TOPIC_DECKS=[{"id":"library-math-place-value-and-rounding","subject":"Math","level":"Grades 5–8","title":"Place value and rounding","cards":[{"question":"What value does 7 have in 3,742?","answer":"700: it is in the hundreds place."},{"question":"Round 4,768 to the nearest hundred.","answer":"4,800. The tens digit is 6, so round the hundreds up."},{"question":"What does a digit’s position tell you?","answer":"Its place value. Each place to the left is ten times the value of the place to its right."}]},{"id":"library-math-fractions","subject":"Math","level":"Grades 5–8","title":"Fractions","cards":[{"question":"What is 1/2 + 1/4?","answer":"2/4 + 1/4 = 3/4."},{"question":"How do you divide by a nonzero fraction?","answer":"Multiply by its reciprocal. For example, 2 ÷ (1/3) = 2 × 3 = 6."},{"question":"Simplify 12/18.","answer":"2/3, dividing the numerator and denominator by 6."}]},{"id":"library-math-decimals-and-percentages","subject":"Math","level":"Grades 5–8","title":"Decimals and percentages","cards":[{"question":"What is 0.35 as a percent?","answer":"35%."},{"question":"Find 20% of 80.","answer":"0.20 × 80 = 16."},{"question":"Convert 3/4 to a decimal.","answer":"3 ÷ 4 = 0.75."}]},{"id":"library-math-ratios-and-proportions","subject":"Math","level":"Grades 5–8","title":"Ratios and proportions","cards":[{"question":"Simplify the ratio 6:9.","answer":"2:3."},{"question":"If 3 notebooks cost $6 at the same unit price, what do 5 cost?","answer":"$10, because each notebook costs $2."},{"question":"Solve x/4 = 3/2.","answer":"x = 6. Multiply both sides by 4."}]},{"id":"library-math-order-of-operations","subject":"Math","level":"Grades 5–8","title":"Order of operations","cards":[{"question":"Evaluate 3 + 4 × 2.","answer":"11. Multiply before adding."},{"question":"Evaluate (3 + 4) × 2.","answer":"14. Evaluate parentheses first."},{"question":"How do you handle multiplication and division of equal priority?","answer":"Work from left to right. Addition and subtraction also share a priority level."}]},{"id":"library-math-negative-numbers-and-integers","subject":"Math","level":"Grades 5–8","title":"Negative numbers and integers","cards":[{"question":"What is −3 + 7?","answer":"4."},{"question":"What is (−4)(−2)?","answer":"8. The product of two negatives is positive."},{"question":"Which is larger: −2 or −5?","answer":"−2: it is farther right on a number line."}]},{"id":"library-math-exponents-and-square-roots","subject":"Math","level":"Grades 5–8","title":"Exponents and square roots","cards":[{"question":"What is 2⁴?","answer":"16: 2 × 2 × 2 × 2."},{"question":"What is √49?","answer":"7, the principal nonnegative square root."},{"question":"Simplify x³ × x².","answer":"x⁵. When multiplying powers with the same base, add exponents."}]},{"id":"library-math-scientific-notation","subject":"Math","level":"Grades 5–8","title":"Scientific notation","cards":[{"question":"Write 45,000 in scientific notation.","answer":"4.5 × 10⁴."},{"question":"Write 0.0032 in scientific notation.","answer":"3.2 × 10⁻³."},{"question":"What coefficient range is used for a positive number in scientific notation?","answer":"At least 1 and less than 10."}]},{"id":"library-math-algebraic-expressions","subject":"Math","level":"Grades 5–8","title":"Algebraic expressions","cards":[{"question":"Simplify 3x + 2x − 4.","answer":"5x − 4."},{"question":"Expand 2(x + 3).","answer":"2x + 6, using the distributive property."},{"question":"Evaluate 2x + 1 when x = 4.","answer":"2(4) + 1 = 9."}]},{"id":"library-math-linear-equations","subject":"Math","level":"Grades 5–8","title":"Linear equations","cards":[{"question":"Solve 2x + 3 = 11.","answer":"Subtract 3: 2x = 8. Divide by 2: x = 4."},{"question":"What keeps an equation balanced?","answer":"Perform the same valid operation on both sides."},{"question":"How do you check a solution?","answer":"Substitute it into the original equation and verify that both sides are equal."}]},{"id":"library-math-inequalities","subject":"Math","level":"Grades 9–12","title":"Inequalities","cards":[{"question":"Solve x + 3 < 8.","answer":"x < 5."},{"question":"Solve −2x > 6.","answer":"x < −3. Reverse the inequality when dividing by a negative."},{"question":"What is the difference between < and ≤?","answer":"< excludes equality; ≤ includes it."}]},{"id":"library-math-systems-of-equations","subject":"Math","level":"Grades 9–12","title":"Systems of equations","cards":[{"question":"Solve x + y = 5 and x − y = 1.","answer":"Add the equations: 2x = 6, so x = 3 and y = 2."},{"question":"What is substitution?","answer":"Solve one equation for a variable, then replace that variable in the other equation."},{"question":"What does the intersection of two line graphs represent?","answer":"A pair of coordinates satisfying both equations."}]},{"id":"library-math-functions-and-domain","subject":"Math","level":"Grades 9–12","title":"Functions and domain","cards":[{"question":"What makes a relation a function?","answer":"Each input in the domain has exactly one output."},{"question":"If f(x) = x² + 1, find f(3).","answer":"10."},{"question":"What is the real-number domain of f(x) = 1/x?","answer":"All real numbers except 0."}]},{"id":"library-math-slope-and-line-graphs","subject":"Math","level":"Grades 9–12","title":"Slope and line graphs","cards":[{"question":"What is the slope formula between distinct x-values?","answer":"m = (y₂ − y₁)/(x₂ − x₁)."},{"question":"What is the slope of y = 3x − 2?","answer":"3; the y-intercept is −2."},{"question":"Find the slope through (0, 1) and (2, 5).","answer":"(5 − 1)/(2 − 0) = 2."}]},{"id":"library-math-quadratic-equations","subject":"Math","level":"Grades 9–12","title":"Quadratic equations","cards":[{"question":"What is the quadratic formula?","answer":"x = (−b ± √(b² − 4ac))/(2a), for ax² + bx + c = 0 with a ≠ 0."},{"question":"Solve x² − 9 = 0.","answer":"x = 3 or x = −3."},{"question":"What does the discriminant tell you for real coefficients?","answer":"b² − 4ac > 0 gives two distinct real roots; 0 gives a repeated real root; < 0 gives nonreal complex roots."}]},{"id":"library-math-factoring","subject":"Math","level":"Grades 9–12","title":"Factoring","cards":[{"question":"Factor x² + 5x + 6.","answer":"(x + 2)(x + 3)."},{"question":"Factor 6x + 9.","answer":"3(2x + 3)."},{"question":"What is a² − b²?","answer":"(a − b)(a + b), the difference of two squares."}]},{"id":"library-math-polynomials","subject":"Math","level":"Grades 9–12","title":"Polynomials","cards":[{"question":"What is the degree of 4x³ + 2x − 1?","answer":"3, the highest exponent with a nonzero coefficient."},{"question":"Expand (x + 1)(x + 2).","answer":"x² + 3x + 2."},{"question":"Combine x² + 2x and 3x² − x.","answer":"4x² + x."}]},{"id":"library-math-angles-and-parallel-lines","subject":"Math","level":"Grades 5–8","title":"Angles and parallel lines","cards":[{"question":"How many degrees are in a straight angle?","answer":"180°."},{"question":"What are complementary angles?","answer":"Two angles whose measures add to 90°."},{"question":"What can you say about corresponding angles formed by a transversal across parallel lines?","answer":"They have equal measures."}]},{"id":"library-math-triangles","subject":"Math","level":"Grades 5–8","title":"Triangles","cards":[{"question":"What is the sum of a triangle’s interior angles in Euclidean geometry?","answer":"180°."},{"question":"What defines an isosceles triangle?","answer":"At least two sides have equal length."},{"question":"A triangle has angles 50° and 60°. Find the third.","answer":"70°, because 180 − 50 − 60 = 70."}]},{"id":"library-math-pythagorean-theorem","subject":"Math","level":"Grades 5–8","title":"Pythagorean theorem","cards":[{"question":"State the Pythagorean theorem.","answer":"For a right triangle, a² + b² = c², where c is the hypotenuse."},{"question":"A right triangle has legs 3 and 4. Find the hypotenuse.","answer":"5, because √(3² + 4²) = √25."},{"question":"Can you apply a² + b² = c² to every triangle?","answer":"No. It applies to right triangles with c opposite the right angle."}]},{"id":"library-math-circles","subject":"Math","level":"Grades 5–8","title":"Circles","cards":[{"question":"What is a circle’s circumference?","answer":"C = 2πr = πd."},{"question":"What is a circle’s area?","answer":"A = πr²."},{"question":"If the radius is 3, what is the diameter?","answer":"6. The diameter is twice the radius."}]},{"id":"library-math-area-surface-area-and-volume","subject":"Math","level":"Grades 5–8","title":"Area, surface area, and volume","cards":[{"question":"What is a rectangle’s area?","answer":"Length × width, in square units."},{"question":"Find the volume of a 2 × 3 × 4 rectangular prism.","answer":"24 cubic units."},{"question":"How does surface area differ from volume?","answer":"Surface area measures the total exterior area in square units; volume measures enclosed space in cubic units."}]},{"id":"library-math-probability","subject":"Math","level":"Grades 5–8","title":"Probability","cards":[{"question":"What is the probability of rolling a 6 on a fair six-sided die?","answer":"1/6."},{"question":"For equally likely outcomes, how do you calculate an event’s probability?","answer":"Favorable outcomes divided by total possible outcomes."},{"question":"What is the probability of not A if P(A) = 0.3?","answer":"0.7, because P(not A) = 1 − P(A)."}]},{"id":"library-math-statistics-and-data","subject":"Math","level":"Grades 5–8","title":"Statistics and data","cards":[{"question":"Find the mean of 2, 4, and 9.","answer":"5: (2 + 4 + 9)/3."},{"question":"Find the median of 1, 3, 8, 10, 12.","answer":"8, the middle value after sorting."},{"question":"Does correlation alone prove causation?","answer":"No. An association by itself does not establish that one variable causes another."}]},{"id":"library-math-precalculus-trigonometry-and-the-unit-circle","subject":"Math","level":"Grades 9–12","title":"Precalculus: trigonometry and the unit circle","cards":[{"question":"On the unit circle, what are the coordinates at angle θ?","answer":"(cos θ, sin θ)."},{"question":"What are sin 90° and cos 90°?","answer":"sin 90° = 1 and cos 90° = 0."},{"question":"In a right triangle, what is sin θ?","answer":"Opposite side / hypotenuse, relative to θ."}]},{"id":"library-math-logarithms-and-exponential-functions","subject":"Math","level":"Grades 9–12","title":"Logarithms and exponential functions","cards":[{"question":"What does log₂ 8 equal?","answer":"3, since 2³ = 8."},{"question":"What does log_b x = y mean?","answer":"bʸ = x, with b > 0, b ≠ 1, and x > 0 for real logarithms."},{"question":"What is e⁰?","answer":"1."}]},{"id":"library-math-limits-and-continuity","subject":"Math","level":"College intro","title":"Limits and continuity","cards":[{"question":"Evaluate lim as x → 2 of (x + 3).","answer":"5."},{"question":"What does a limit describe?","answer":"The value a function approaches as its input approaches a specified value."},{"question":"What conditions make f continuous at a?","answer":"f(a) is defined, the limit as x → a exists, and that limit equals f(a)."}]},{"id":"library-math-derivatives","subject":"Math","level":"College intro","title":"Derivatives","cards":[{"question":"What does a derivative describe?","answer":"An instantaneous rate of change; geometrically, the tangent slope where the derivative exists."},{"question":"Differentiate x³ with respect to x.","answer":"3x²."},{"question":"Differentiate 5x + 2.","answer":"5."}]},{"id":"library-math-integrals","subject":"Math","level":"College intro","title":"Integrals","cards":[{"question":"What is an antiderivative of 2x?","answer":"x² + C."},{"question":"Evaluate the definite integral of 1 from 0 to 3.","answer":"3."},{"question":"What is a definite integral’s geometric interpretation?","answer":"Signed accumulation: area above the x-axis counts positively and area below counts negatively."}]},{"id":"library-math-vectors-and-matrices","subject":"Math","level":"College intro","title":"Vectors and matrices","cards":[{"question":"Add vectors (1, 2) and (3, 4).","answer":"(4, 6), adding corresponding components."},{"question":"Find the dot product of (1, 2) and (3, 4).","answer":"1×3 + 2×4 = 11."},{"question":"When can an m×n matrix multiply a p×q matrix?","answer":"When n = p. The result is m×q."}]},{"id":"library-math-sequences-and-series","subject":"Math","level":"Grades 9–12","title":"Sequences and series","cards":[{"question":"Find the nth term of an arithmetic sequence.","answer":"aₙ = a₁ + (n − 1)d, where d is the common difference."},{"question":"What is the next term after 2, 6, 18?","answer":"54, multiplying by the common ratio 3."},{"question":"How does a series differ from a sequence?","answer":"A sequence is an ordered list; a series is a sum of sequence terms."}]},{"id":"library-math-complex-numbers","subject":"Math","level":"Grades 9–12","title":"Complex numbers","cards":[{"question":"What does i² equal?","answer":"−1."},{"question":"Simplify (2 + 3i) + (1 − i).","answer":"3 + 2i."},{"question":"What is the complex conjugate of 4 + 5i?","answer":"4 − 5i."}]},{"id":"library-math-counting-and-combinatorics","subject":"Math","level":"Grades 9–12","title":"Counting and combinatorics","cards":[{"question":"What is 4 factorial?","answer":"4! = 4 × 3 × 2 × 1 = 24."},{"question":"How do permutations and combinations differ?","answer":"Permutations consider order; combinations do not."},{"question":"How many pairs can you choose from 4 different people?","answer":"6: C(4,2) = 4!/(2!2!)."}]},{"id":"library-math-sets-and-mathematical-logic","subject":"Math","level":"College intro","title":"Sets and mathematical logic","cards":[{"question":"What is A ∩ B?","answer":"The intersection: elements belonging to both A and B."},{"question":"What is A ∪ B?","answer":"The union: elements belonging to A, B, or both."},{"question":"What is the contrapositive of “If P, then Q”?","answer":"If not Q, then not P. It is logically equivalent to the original implication."}]},{"id":"library-math-proofs-and-reasoning","subject":"Math","level":"Grades 9–12","title":"Proofs and reasoning","cards":[{"question":"What is a counterexample?","answer":"An example showing that a universal claim is false."},{"question":"What is a direct proof?","answer":"A chain of valid deductions from assumptions to the conclusion."},{"question":"Does checking a few examples prove a statement for every integer?","answer":"No. Examples can suggest a pattern, but a general proof is needed."}]},{"id":"library-math-factors-multiples-and-primes","subject":"Math","level":"Grades 5–8","title":"Factors, multiples, and primes","cards":[{"question":"What is a prime number?","answer":"An integer greater than 1 with exactly two positive factors: 1 and itself."},{"question":"Find the greatest common factor of 12 and 18.","answer":"6."},{"question":"Find the least common multiple of 4 and 6.","answer":"12."}]},{"id":"library-biology-cells-and-cell-theory","subject":"Biology","level":"Grades 5–8","title":"Cells and cell theory","cards":[{"question":"What is a cell?","answer":"The basic unit of life."},{"question":"What are the main ideas of cell theory?","answer":"Living things consist of cells; cells are basic units of life; cells arise from existing cells."},{"question":"How do prokaryotic and eukaryotic cells differ?","answer":"Eukaryotic cells have a membrane-bound nucleus; prokaryotic cells do not."}]},{"id":"library-biology-organelles","subject":"Biology","level":"Grades 5–8","title":"Organelles","cards":[{"question":"What is the nucleus’s main role?","answer":"It contains most of a eukaryotic cell’s DNA."},{"question":"What do ribosomes do?","answer":"Build proteins by translating messenger RNA."},{"question":"What do mitochondria do?","answer":"Carry out major steps of aerobic cellular respiration that produce ATP."}]},{"id":"library-biology-cell-membranes-and-transport","subject":"Biology","level":"Grades 9–12","title":"Cell membranes and transport","cards":[{"question":"What is diffusion?","answer":"Net movement of particles down a concentration gradient."},{"question":"What is osmosis?","answer":"Movement of water across a selectively permeable membrane."},{"question":"What distinguishes active transport?","answer":"It uses energy to move substances against their electrochemical gradient, directly or through coupled transport."}]},{"id":"library-biology-enzymes","subject":"Biology","level":"Grades 9–12","title":"Enzymes","cards":[{"question":"What are enzymes?","answer":"Biological catalysts that speed reactions by lowering activation energy."},{"question":"Are enzymes consumed by the reactions they catalyze?","answer":"No. They can be reused."},{"question":"How can high temperatures affect an enzyme?","answer":"They can disrupt its structure and reduce or eliminate activity."}]},{"id":"library-biology-photosynthesis","subject":"Biology","level":"Grades 5–8","title":"Photosynthesis","cards":[{"question":"What energy source powers photosynthesis in plants?","answer":"Light, usually sunlight."},{"question":"What are the overall reactants of oxygen-producing photosynthesis?","answer":"Carbon dioxide and water, with light energy."},{"question":"What are its overall products?","answer":"Sugars and oxygen."}]},{"id":"library-biology-cellular-respiration","subject":"Biology","level":"Grades 9–12","title":"Cellular respiration","cards":[{"question":"What is ATP’s role in cells?","answer":"It transfers energy to support cellular work."},{"question":"Where does glycolysis occur?","answer":"In the cytosol."},{"question":"Do plants perform cellular respiration?","answer":"Yes. Plant cells also need usable energy."}]},{"id":"library-biology-mitosis","subject":"Biology","level":"Grades 9–12","title":"Mitosis","cards":[{"question":"What is mitosis?","answer":"Division of a eukaryotic nucleus that usually produces genetically equivalent nuclei."},{"question":"What is cytokinesis?","answer":"Division of the cytoplasm into daughter cells."},{"question":"Why do multicellular organisms use mitosis?","answer":"For growth, repair, and replacement of cells."}]},{"id":"library-biology-meiosis","subject":"Biology","level":"Grades 9–12","title":"Meiosis","cards":[{"question":"What does meiosis do to chromosome number?","answer":"It reduces chromosome number by half, producing haploid cells from a diploid starting cell."},{"question":"How many nuclear divisions occur in meiosis?","answer":"Two: meiosis I and meiosis II."},{"question":"How does crossing over contribute to variation?","answer":"Homologous chromosomes exchange DNA segments, producing new combinations of alleles."}]},{"id":"library-biology-dna-rna-and-protein-synthesis","subject":"Biology","level":"Grades 9–12","title":"DNA, RNA, and protein synthesis","cards":[{"question":"What bases pair in DNA?","answer":"A with T, and C with G."},{"question":"What is transcription?","answer":"Making an RNA copy using a DNA template."},{"question":"What is translation?","answer":"Using an mRNA sequence to build a polypeptide at a ribosome."}]},{"id":"library-biology-mendelian-genetics","subject":"Biology","level":"Grades 9–12","title":"Mendelian genetics","cards":[{"question":"What is an allele?","answer":"A version of a gene."},{"question":"What is the difference between genotype and phenotype?","answer":"Genotype describes genetic makeup; phenotype describes observable traits influenced by genes and environment."},{"question":"For a simple completely dominant trait, what fraction of Aa × Aa offspring are expected to be aa?","answer":"1/4, or 25%, assuming ordinary Mendelian inheritance."}]},{"id":"library-biology-evolution-and-natural-selection","subject":"Biology","level":"Grades 9–12","title":"Evolution and natural selection","cards":[{"question":"What is natural selection?","answer":"Heritable traits affecting reproductive success can become more or less common over generations."},{"question":"Do individual organisms evolve during their lifetimes?","answer":"Evolution describes changes in populations across generations, not an individual choosing to change."},{"question":"What is a mutation?","answer":"A change in DNA sequence; mutations can introduce genetic variation."}]},{"id":"library-biology-ecology-and-food-webs","subject":"Biology","level":"Grades 5–8","title":"Ecology and food webs","cards":[{"question":"What is an ecosystem?","answer":"Organisms and the nonliving environment with which they interact."},{"question":"What is a producer in a food web?","answer":"An organism that makes organic food from inorganic materials using light or chemical energy."},{"question":"What do arrows in a food chain commonly represent?","answer":"The direction of energy transfer, from a food source to its consumer."}]},{"id":"library-biology-homeostasis-and-human-body-systems","subject":"Biology","level":"Grades 9–12","title":"Homeostasis and human body systems","cards":[{"question":"What is homeostasis?","answer":"Maintenance of relatively stable internal conditions."},{"question":"What is negative feedback?","answer":"A response that counteracts a change, helping maintain a regulated condition."},{"question":"What is the circulatory system’s main transport role?","answer":"Moving blood to deliver substances such as oxygen and nutrients and carry wastes away."}]},{"id":"library-biology-classification-and-biodiversity","subject":"Biology","level":"Grades 9–12","title":"Classification and biodiversity","cards":[{"question":"What is binomial nomenclature?","answer":"A two-part species name made of genus and specific epithet."},{"question":"What is biodiversity?","answer":"The variety of life, including genetic, species, and ecosystem diversity."},{"question":"What do the branches of a phylogenetic tree represent?","answer":"Hypothesized evolutionary relationships among lineages."}]},{"id":"library-science-chemistry-atoms-and-elements","subject":"Science","level":"Grades 5–8","title":"Chemistry: atoms and elements","cards":[{"question":"What are the charges of protons, electrons, and neutrons?","answer":"Protons are positive, electrons negative, and neutrons neutral."},{"question":"What determines an element’s atomic number?","answer":"Its number of protons."},{"question":"What is an isotope?","answer":"An atom of an element with a particular neutron number; isotopes of the same element differ in neutrons."}]},{"id":"library-science-chemistry-the-periodic-table","subject":"Science","level":"Grades 9–12","title":"Chemistry: the periodic table","cards":[{"question":"What is a group on the periodic table?","answer":"A vertical column; main-group elements in a group often share valence-electron patterns."},{"question":"What is a period?","answer":"A horizontal row."},{"question":"Where are noble gases found?","answer":"Group 18."}]},{"id":"library-science-chemistry-ions-and-bonding","subject":"Science","level":"Grades 9–12","title":"Chemistry: ions and bonding","cards":[{"question":"What is a cation?","answer":"A positively charged ion."},{"question":"How do ionic and covalent bonding differ?","answer":"Ionic bonding involves attraction between oppositely charged ions; covalent bonding involves shared electron pairs."},{"question":"What charge does a sodium atom have after losing one electron?","answer":"+1, forming Na⁺."}]},{"id":"library-science-chemistry-balancing-equations","subject":"Science","level":"Grades 9–12","title":"Chemistry: balancing equations","cards":[{"question":"Why must chemical equations be balanced?","answer":"Atoms are conserved in ordinary chemical reactions."},{"question":"Balance H₂ + O₂ → H₂O.","answer":"2H₂ + O₂ → 2H₂O."},{"question":"When balancing, should you change subscripts in chemical formulas?","answer":"No. Change coefficients; changing subscripts changes the substances."}]},{"id":"library-science-chemistry-moles-and-stoichiometry","subject":"Science","level":"Grades 9–12","title":"Chemistry: moles and stoichiometry","cards":[{"question":"What does one mole contain?","answer":"Exactly 6.02214076 × 10²³ specified entities."},{"question":"How do you convert grams to moles?","answer":"Divide mass in grams by molar mass in grams per mole."},{"question":"In 2H₂ + O₂ → 2H₂O, what is the H₂:O₂ mole ratio?","answer":"2:1."}]},{"id":"library-science-chemistry-acids-bases-and-ph","subject":"Science","level":"Grades 9–12","title":"Chemistry: acids, bases, and pH","cards":[{"question":"At 25°C, what is the pH of neutral water?","answer":"7."},{"question":"In the Brønsted–Lowry model, what does an acid do?","answer":"Donates a proton; a base accepts a proton."},{"question":"How does hydrogen-ion activity change when pH decreases by 1?","answer":"It increases by a factor of 10."}]},{"id":"library-science-chemistry-solutions-and-concentration","subject":"Science","level":"Grades 9–12","title":"Chemistry: solutions and concentration","cards":[{"question":"What are a solute and a solvent?","answer":"A solute is dissolved; a solvent is the dissolving medium."},{"question":"What is molarity?","answer":"Moles of solute per liter of solution."},{"question":"Find the molarity of 0.5 mol in 2 L of solution.","answer":"0.25 M."}]},{"id":"library-science-states-of-matter","subject":"Science","level":"Grades 5–8","title":"States of matter","cards":[{"question":"How do solids, liquids, and gases differ in shape and volume?","answer":"Solids retain shape and volume; liquids retain volume but take a container’s shape; gases expand to fill their container."},{"question":"What is evaporation?","answer":"Liquid changing to gas at its surface."},{"question":"What is condensation?","answer":"Gas changing to liquid."}]},{"id":"library-science-chemistry-equilibrium","subject":"Science","level":"College intro","title":"Chemistry: equilibrium","cards":[{"question":"What is dynamic chemical equilibrium?","answer":"Forward and reverse reaction rates are equal, so macroscopic concentrations remain constant."},{"question":"Does equilibrium require equal reactant and product concentrations?","answer":"No. Their concentrations can differ."},{"question":"What does Le Châtelier’s principle describe?","answer":"How an equilibrium system tends to respond to a disturbance by partially counteracting it."}]},{"id":"library-science-chemistry-oxidation-and-reduction","subject":"Science","level":"College intro","title":"Chemistry: oxidation and reduction","cards":[{"question":"What happens in oxidation?","answer":"Loss of electrons."},{"question":"What happens in reduction?","answer":"Gain of electrons."},{"question":"Can oxidation occur without a corresponding reduction in a redox reaction?","answer":"No. Electrons lost by one species are gained by another."}]},{"id":"library-science-physics-motion-and-speed","subject":"Science","level":"Grades 5–8","title":"Physics: motion and speed","cards":[{"question":"What is average speed?","answer":"Total distance traveled divided by elapsed time."},{"question":"How does velocity differ from speed?","answer":"Velocity includes direction; speed is a scalar magnitude."},{"question":"Travel 100 m in 20 s. Find average speed.","answer":"5 m/s."}]},{"id":"library-science-physics-newton-s-laws","subject":"Science","level":"Grades 9–12","title":"Physics: Newton’s laws","cards":[{"question":"State Newton’s second law for constant mass.","answer":"Net force F = ma."},{"question":"What happens to an object with zero net external force in an inertial frame?","answer":"Its velocity stays constant."},{"question":"Why do action–reaction forces not cancel on one object?","answer":"They act on different objects."}]},{"id":"library-science-physics-work-and-energy","subject":"Science","level":"Grades 9–12","title":"Physics: work and energy","cards":[{"question":"What is kinetic energy for a nonrelativistic object?","answer":"KE = ½mv²."},{"question":"What is mechanical work by a constant force?","answer":"W = Fd cos θ, where θ is the angle between force and displacement."},{"question":"What does conservation of energy mean?","answer":"Energy can be transferred or transformed; total energy in an isolated system remains constant."}]},{"id":"library-science-physics-momentum","subject":"Science","level":"Grades 9–12","title":"Physics: momentum","cards":[{"question":"What is linear momentum?","answer":"p = mv."},{"question":"When is total momentum conserved?","answer":"When the net external force on the system is zero."},{"question":"What is impulse?","answer":"The change in momentum, equal to the integral of force over time."}]},{"id":"library-science-physics-waves-and-sound","subject":"Science","level":"Grades 5–8","title":"Physics: waves and sound","cards":[{"question":"What is frequency?","answer":"The number of cycles per unit time."},{"question":"Relate wave speed, frequency, and wavelength.","answer":"v = fλ."},{"question":"Can sound travel through a vacuum?","answer":"No. Sound requires a material medium."}]},{"id":"library-science-physics-electricity-and-circuits","subject":"Science","level":"Grades 9–12","title":"Physics: electricity and circuits","cards":[{"question":"State Ohm’s law for an ohmic resistor.","answer":"V = IR."},{"question":"What is electric current?","answer":"Rate of flow of electric charge."},{"question":"A 6 V supply is across a 3 Ω resistor. Find current.","answer":"2 A, using I = V/R."}]},{"id":"library-science-physics-magnetism","subject":"Science","level":"Grades 9–12","title":"Physics: magnetism","cards":[{"question":"What produces a magnetic field around a wire?","answer":"An electric current."},{"question":"What happens to like magnetic poles?","answer":"They repel; unlike poles attract."},{"question":"What is electromagnetic induction?","answer":"Production of an electromotive force by a changing magnetic flux."}]},{"id":"library-science-physics-gravity","subject":"Science","level":"Grades 9–12","title":"Physics: gravity","cards":[{"question":"What is gravitational force between two point masses?","answer":"F = Gm₁m₂/r²."},{"question":"How do mass and weight differ?","answer":"Mass is a measure of inertia; weight is gravitational force."},{"question":"What happens to the gravitational force if separation doubles?","answer":"It becomes one quarter as large, with the masses unchanged."}]},{"id":"library-science-earth-science-rocks-and-minerals","subject":"Science","level":"Grades 5–8","title":"Earth science: rocks and minerals","cards":[{"question":"What are the three main rock types?","answer":"Igneous, sedimentary, and metamorphic."},{"question":"How do igneous rocks form?","answer":"From cooling and solidifying magma or lava."},{"question":"What can transform a rock into metamorphic rock?","answer":"Heat, pressure, and/or chemically active fluids without fully melting it."}]},{"id":"library-science-earth-science-plate-tectonics","subject":"Science","level":"Grades 5–8","title":"Earth science: plate tectonics","cards":[{"question":"What are tectonic plates?","answer":"Large moving pieces of Earth’s lithosphere."},{"question":"What happens at a divergent plate boundary?","answer":"Plates move apart."},{"question":"What happens at a convergent plate boundary?","answer":"Plates move toward each other, sometimes causing subduction or mountain building."}]},{"id":"library-science-weather-and-climate","subject":"Science","level":"Grades 5–8","title":"Weather and climate","cards":[{"question":"How do weather and climate differ?","answer":"Weather concerns short-term atmospheric conditions; climate concerns long-term patterns."},{"question":"What is the water cycle?","answer":"Movement of water through processes including evaporation, condensation, precipitation, and runoff."},{"question":"What is the greenhouse effect?","answer":"Atmospheric gases absorb and emit infrared radiation, affecting Earth’s energy balance."}]},{"id":"library-science-the-solar-system","subject":"Science","level":"Grades 5–8","title":"The solar system","cards":[{"question":"What keeps planets in orbit around the Sun?","answer":"Gravity together with their motion."},{"question":"What causes seasons on Earth?","answer":"Earth’s tilted axis as Earth orbits the Sun, changing sunlight angle and day length."},{"question":"What causes Moon phases?","answer":"Our changing view of the Moon’s sunlit half as it orbits Earth."}]},{"id":"library-science-astronomy-stars-and-galaxies","subject":"Science","level":"Grades 9–12","title":"Astronomy: stars and galaxies","cards":[{"question":"What is a star?","answer":"A self-gravitating luminous object powered for much of its life by nuclear fusion."},{"question":"What is a galaxy?","answer":"A large gravitationally bound system of stars, gas, dust, and other matter."},{"question":"What is a light-year?","answer":"A unit of distance: the distance light travels in one year in vacuum."}]},{"id":"library-science-scientific-measurement-and-uncertainty","subject":"Science","level":"College intro","title":"Scientific measurement and uncertainty","cards":[{"question":"What does measurement uncertainty communicate?","answer":"A range or quantified limit to how precisely a measured value is known."},{"question":"How do accuracy and precision differ?","answer":"Accuracy concerns closeness to a reference value; precision concerns agreement among repeated measurements."},{"question":"Why report units with numerical measurements?","answer":"Units identify what quantity is measured and allow meaningful comparison and calculation."}]},{"id":"library-ela-parts-of-speech","subject":"ELA","level":"Grades 5–8","title":"Parts of speech","cards":[{"question":"What does a noun name?","answer":"A person, place, thing, or idea."},{"question":"What does a verb express?","answer":"An action, occurrence, or state of being."},{"question":"What does an adjective typically modify?","answer":"A noun or pronoun."}]},{"id":"library-ela-sentence-structure","subject":"ELA","level":"Grades 5–8","title":"Sentence structure","cards":[{"question":"What is an independent clause?","answer":"A clause that can stand alone as a complete sentence."},{"question":"What is a compound sentence?","answer":"A sentence containing at least two independent clauses."},{"question":"What is a sentence fragment?","answer":"A group of words presented as a sentence that lacks a complete independent clause."}]},{"id":"library-ela-subject-verb-agreement","subject":"ELA","level":"Grades 5–8","title":"Subject–verb agreement","cards":[{"question":"Choose the standard form: “She walk” or “She walks.”","answer":"She walks."},{"question":"Which word controls the verb in “The box of pencils is here”?","answer":"The singular subject “box,” not “pencils.”"},{"question":"Choose the standard form: “They is ready” or “They are ready.”","answer":"They are ready."}]},{"id":"library-ela-punctuation","subject":"ELA","level":"Grades 5–8","title":"Punctuation","cards":[{"question":"What separates items in a simple series?","answer":"Commas."},{"question":"What can a semicolon join?","answer":"Two closely related independent clauses."},{"question":"What is a comma splice?","answer":"Two independent clauses incorrectly joined by only a comma."}]},{"id":"library-ela-pronouns-and-antecedents","subject":"ELA","level":"Grades 5–8","title":"Pronouns and antecedents","cards":[{"question":"What is an antecedent?","answer":"The noun or noun phrase a pronoun refers to."},{"question":"Why should pronoun reference be clear?","answer":"Readers need to know which person or thing the pronoun identifies."},{"question":"Identify the pronoun in “Maya said she would help.”","answer":"“She,” referring to Maya in this reading."}]},{"id":"library-ela-vocabulary-and-context-clues","subject":"ELA","level":"Grades 5–8","title":"Vocabulary and context clues","cards":[{"question":"What is a synonym?","answer":"A word with a similar meaning in a particular context."},{"question":"What is an antonym?","answer":"A word with an opposite or contrasting meaning."},{"question":"How can context help with an unfamiliar word?","answer":"Nearby definitions, examples, contrasts, and descriptions can suggest its meaning."}]},{"id":"library-ela-main-idea-and-supporting-details","subject":"ELA","level":"Grades 5–8","title":"Main idea and supporting details","cards":[{"question":"What is a text’s main idea?","answer":"Its central point or overall message about the topic."},{"question":"What are supporting details?","answer":"Information, examples, or evidence developing the main idea."},{"question":"How does a topic differ from a main idea?","answer":"The topic names what the text concerns; the main idea states a point about that topic."}]},{"id":"library-ela-theme-and-inference","subject":"ELA","level":"Grades 5–8","title":"Theme and inference","cards":[{"question":"What is a literary theme?","answer":"An idea or insight about life or experience developed by a work."},{"question":"What is an inference?","answer":"A conclusion drawn from evidence and reasoning, even if not stated directly."},{"question":"Why should you support an interpretation with textual evidence?","answer":"It shows how your reading connects to details in the work."}]},{"id":"library-ela-figurative-language","subject":"ELA","level":"Grades 5–8","title":"Figurative language","cards":[{"question":"What is a simile?","answer":"A comparison commonly using “like” or “as.”"},{"question":"What is a metaphor?","answer":"A figure of speech describing one thing as another to suggest a comparison."},{"question":"What is personification?","answer":"Giving human qualities to something nonhuman."}]},{"id":"library-ela-plot-and-characterization","subject":"ELA","level":"Grades 9–12","title":"Plot and characterization","cards":[{"question":"What is conflict in a story?","answer":"A struggle between opposing forces, including internal struggles."},{"question":"What is characterization?","answer":"How a text develops a character through description, actions, dialogue, and other details."},{"question":"What is a story’s climax?","answer":"A major turning point or moment of heightened conflict."}]},{"id":"library-ela-point-of-view-and-narration","subject":"ELA","level":"Grades 9–12","title":"Point of view and narration","cards":[{"question":"What is first-person narration?","answer":"A narrator tells the story using forms such as “I” or “we.”"},{"question":"What is third-person limited narration?","answer":"Narration using third-person forms with access mainly to one character’s perspective."},{"question":"What is an unreliable narrator?","answer":"A narrator whose account gives readers reason to question its accuracy or completeness."}]},{"id":"library-ela-poetry","subject":"ELA","level":"Grades 9–12","title":"Poetry","cards":[{"question":"What is imagery?","answer":"Language appealing to the senses."},{"question":"What is a stanza?","answer":"A grouped set of lines in a poem."},{"question":"How do tone and mood differ?","answer":"Tone concerns the speaker’s or work’s attitude; mood concerns the feeling evoked for a reader."}]},{"id":"library-ela-thesis-statements-and-essays","subject":"ELA","level":"Grades 9–12","title":"Thesis statements and essays","cards":[{"question":"What does a thesis statement do?","answer":"Expresses the central claim or controlling idea an essay develops."},{"question":"What is a topic sentence?","answer":"A sentence stating or guiding the main point of a paragraph."},{"question":"Why revise an essay’s organization?","answer":"To make the reasoning and progression of ideas easier to follow."}]},{"id":"library-ela-argument-and-evidence","subject":"ELA","level":"Grades 9–12","title":"Argument and evidence","cards":[{"question":"How does a claim differ from evidence?","answer":"A claim is a position or assertion; evidence is information used to support it."},{"question":"What is a counterargument?","answer":"A reasoned challenge to a position that a writer can address."},{"question":"What is a logical fallacy?","answer":"An error in reasoning that weakens an argument."}]},{"id":"library-ela-research-citations-and-academic-integrity","subject":"ELA","level":"College intro","title":"Research, citations, and academic integrity","cards":[{"question":"Why cite a source?","answer":"To credit others’ work and let readers locate the evidence used."},{"question":"Does paraphrasing remove the need to cite a borrowed idea?","answer":"No. Borrowed ideas still need attribution."},{"question":"What is the difference between quoting and paraphrasing?","answer":"Quoting uses exact source wording with quotation conventions; paraphrasing restates an idea in your own wording and structure, with citation."}]},{"id":"library-ela-rhetorical-analysis","subject":"ELA","level":"College intro","title":"Rhetorical analysis","cards":[{"question":"What is ethos?","answer":"An appeal related to credibility or character."},{"question":"What is logos?","answer":"An appeal using reasoning and evidence."},{"question":"What is pathos?","answer":"An appeal engaging an audience’s emotions."}]},{"id":"library-history-historical-sources-and-evidence","subject":"History","level":"Grades 5–8","title":"Historical sources and evidence","cards":[{"question":"What is a primary source?","answer":"Evidence created by participants or observers of the time or event being studied."},{"question":"What is a secondary source?","answer":"A later account or analysis interpreting information about the past."},{"question":"Why examine a source’s author, audience, and purpose?","answer":"They help assess perspective, context, and the uses and limits of the evidence."}]},{"id":"library-history-ancient-mesopotamia","subject":"History","level":"Grades 5–8","title":"Ancient Mesopotamia","cards":[{"question":"Between which rivers did much of ancient Mesopotamia develop?","answer":"The Tigris and Euphrates."},{"question":"What was cuneiform?","answer":"A writing system using wedge-shaped marks, developed in ancient Mesopotamia."},{"question":"What is a city-state?","answer":"A city and its surrounding territory functioning as an independent political unit."}]},{"id":"library-history-ancient-egypt","subject":"History","level":"Grades 5–8","title":"Ancient Egypt","cards":[{"question":"Which river was central to ancient Egyptian civilization?","answer":"The Nile."},{"question":"What was a pharaoh?","answer":"A ruler of ancient Egypt."},{"question":"Why were annual Nile floods important to agriculture?","answer":"They supplied water and deposited fertile sediment."}]},{"id":"library-history-ancient-greece-and-rome","subject":"History","level":"Grades 5–8","title":"Ancient Greece and Rome","cards":[{"question":"What was the Athenian polis?","answer":"The city-state of Athens and its community."},{"question":"Was ancient Athenian democracy open to everyone?","answer":"No. Political participation was restricted, excluding women, enslaved people, and many other residents."},{"question":"How did the Roman Republic differ from rule by an emperor?","answer":"Republican government used institutions such as assemblies and elected magistrates; imperial government concentrated authority in an emperor."}]},{"id":"library-history-medieval-societies-and-trade","subject":"History","level":"Grades 5–8","title":"Medieval societies and trade","cards":[{"question":"What were manors in medieval Europe?","answer":"Agricultural estates involving landowners and dependent farming communities."},{"question":"What were the Silk Roads?","answer":"Interconnected routes linking regions of Eurasia through exchange of goods, ideas, and technologies."},{"question":"Was the medieval period identical in every region?","answer":"No. Societies across Europe, Africa, Asia, and the Americas followed diverse developments."}]},{"id":"library-history-the-renaissance","subject":"History","level":"Grades 9–12","title":"The Renaissance","cards":[{"question":"What does “Renaissance” mean?","answer":"“Rebirth,” commonly referring to renewed engagement with classical learning and major cultural changes in Europe."},{"question":"What was Renaissance humanism?","answer":"A scholarly movement emphasizing classical texts and the study of human language, history, and culture."},{"question":"How did printing with movable type affect European learning?","answer":"It helped texts circulate more widely and rapidly."}]},{"id":"library-history-the-reformation","subject":"History","level":"Grades 9–12","title":"The Reformation","cards":[{"question":"What was the Protestant Reformation?","answer":"A set of sixteenth-century movements challenging aspects of Catholic authority and practice in Europe."},{"question":"Who is associated with the Ninety-Five Theses in 1517?","answer":"Martin Luther."},{"question":"Did the Reformation have only religious effects?","answer":"No. It also affected politics, education, conflict, and social life."}]},{"id":"library-history-colonization-and-atlantic-exchange","subject":"History","level":"Grades 9–12","title":"Colonization and Atlantic exchange","cards":[{"question":"What was the Columbian Exchange?","answer":"Transfers of organisms, crops, diseases, and other things between the Americas and other regions after 1492."},{"question":"How did colonization affect Indigenous peoples?","answer":"Effects included dispossession, disease, violence, coerced labor, and major cultural and political disruptions, alongside resistance."},{"question":"What was the transatlantic slave trade?","answer":"The forced transportation of millions of enslaved Africans across the Atlantic."}]},{"id":"library-history-the-enlightenment","subject":"History","level":"Grades 9–12","title":"The Enlightenment","cards":[{"question":"What was the Enlightenment?","answer":"An intellectual movement emphasizing reason and debate about knowledge, society, and government."},{"question":"What is separation of powers?","answer":"Dividing governmental authority among different institutions."},{"question":"What is a social contract theory?","answer":"An account of political authority grounded in an agreement, real or hypothetical, among members of society."}]},{"id":"library-history-the-american-revolution","subject":"History","level":"Grades 5–8","title":"The American Revolution","cards":[{"question":"In what year was the Declaration of Independence adopted?","answer":"1776."},{"question":"What was a major colonial complaint about British taxation?","answer":"Colonists challenged taxation without representation in Parliament."},{"question":"Did independence immediately create equal rights for everyone?","answer":"No. Enslavement and many exclusions from political and legal equality continued."}]},{"id":"library-history-the-french-revolution","subject":"History","level":"Grades 9–12","title":"The French Revolution","cards":[{"question":"In what year did the French Revolution begin?","answer":"1789."},{"question":"What were the three estates in pre-revolutionary France?","answer":"Clergy, nobility, and the Third Estate, which included most people."},{"question":"Name major pressures contributing to the revolution.","answer":"Financial crisis, social inequalities, political conflict, and challenges to royal authority."}]},{"id":"library-history-the-industrial-revolution","subject":"History","level":"Grades 9–12","title":"The Industrial Revolution","cards":[{"question":"What characterized the Industrial Revolution?","answer":"Major growth in mechanized production, factories, and new energy uses."},{"question":"Why was the steam engine important?","answer":"It supplied power for industry and transportation beyond reliance on wind, water, or muscle alone."},{"question":"Name a social effect of industrialization.","answer":"Urban growth and major changes in working conditions, family life, and class relations."}]},{"id":"library-history-the-u-s-civil-war-and-reconstruction","subject":"History","level":"Grades 9–12","title":"The U.S. Civil War and Reconstruction","cards":[{"question":"When was the U.S. Civil War fought?","answer":"1861–1865."},{"question":"What institution was central to the conflict leading to secession?","answer":"Slavery, including conflict over its preservation and expansion."},{"question":"What did the Thirteenth Amendment do?","answer":"Abolished slavery and involuntary servitude, except as punishment for a crime after conviction."}]},{"id":"library-history-world-war-i","subject":"History","level":"Grades 9–12","title":"World War I","cards":[{"question":"When did World War I take place?","answer":"1914–1918."},{"question":"What event triggered the July Crisis of 1914?","answer":"The assassination of Archduke Franz Ferdinand in Sarajevo."},{"question":"Why is it incomplete to explain the war with only one cause?","answer":"Alliance systems, imperial rivalries, militarism, nationalism, and political decisions also contributed."}]},{"id":"library-history-world-war-ii-and-the-holocaust","subject":"History","level":"Grades 9–12","title":"World War II and the Holocaust","cards":[{"question":"When did World War II take place?","answer":"1939–1945."},{"question":"What event is commonly used to mark the beginning of the war in Europe?","answer":"Germany’s invasion of Poland in September 1939."},{"question":"What was the Holocaust?","answer":"The systematic persecution and murder of six million Jews by Nazi Germany and its collaborators; the Nazi regime also persecuted and murdered other groups."}]},{"id":"library-history-the-cold-war","subject":"History","level":"Grades 9–12","title":"The Cold War","cards":[{"question":"What was the Cold War?","answer":"A prolonged geopolitical rivalry centered on the United States and the Soviet Union and their allies after World War II."},{"question":"What is a proxy war?","answer":"A conflict in which outside powers support opposing participants rather than directly fighting each other as the main adversaries."},{"question":"What major event occurred in 1991?","answer":"The dissolution of the Soviet Union."}]},{"id":"library-history-civil-rights-movements","subject":"History","level":"Grades 9–12","title":"Civil rights movements","cards":[{"question":"What did the U.S. Civil Rights Act of 1964 address?","answer":"Discrimination in areas including public accommodations and employment."},{"question":"What did the Voting Rights Act of 1965 aim to protect?","answer":"Voting rights, especially against racial discrimination."},{"question":"Why study both famous leaders and grassroots organizers?","answer":"Movements depend on many participants, organizations, and local efforts, not only well-known individuals."}]},{"id":"library-history-decolonization","subject":"History","level":"Grades 9–12","title":"Decolonization","cards":[{"question":"What is decolonization?","answer":"Processes through which colonized territories and peoples challenge or end colonial rule."},{"question":"In what year did India gain independence from Britain?","answer":"1947, alongside partition and the creation of Pakistan."},{"question":"Did decolonization follow a single pattern everywhere?","answer":"No. Processes varied, including negotiation, protest, armed struggle, and different post-independence challenges."}]},{"id":"library-geography-maps-latitude-and-longitude","subject":"Geography","level":"Grades 5–8","title":"Maps, latitude, and longitude","cards":[{"question":"What does latitude measure?","answer":"Angular distance north or south of the equator."},{"question":"What does longitude measure?","answer":"Angular distance east or west of the prime meridian."},{"question":"What does a map scale show?","answer":"How distance on a map relates to distance on the ground."}]},{"id":"library-geography-continents-and-oceans","subject":"Geography","level":"Grades 5–8","title":"Continents and oceans","cards":[{"question":"Name the seven continents in a common English-language model.","answer":"Africa, Antarctica, Asia, Europe, North America, Australia, and South America."},{"question":"What is the largest ocean?","answer":"The Pacific Ocean."},{"question":"Why do different sources sometimes count continents differently?","answer":"Continental divisions involve geographic and cultural conventions as well as physical features."}]},{"id":"library-geography-population-and-migration","subject":"Geography","level":"Grades 5–8","title":"Population and migration","cards":[{"question":"What is population density?","answer":"The number of people per unit area."},{"question":"What is migration?","answer":"Movement of people from one place to another, temporarily or permanently."},{"question":"How do push and pull factors differ?","answer":"Push factors encourage people to leave; pull factors attract them to a destination."}]},{"id":"library-geography-human-geography-and-urbanization","subject":"Geography","level":"Grades 9–12","title":"Human geography and urbanization","cards":[{"question":"What is urbanization?","answer":"Growth in the proportion of people living in urban areas and associated changes."},{"question":"What is cultural diffusion?","answer":"Spread of cultural practices, ideas, or technologies between groups."},{"question":"What is a region?","answer":"An area grouped by shared characteristics or relationships."}]},{"id":"library-geography-resources-and-sustainability","subject":"Geography","level":"Grades 9–12","title":"Resources and sustainability","cards":[{"question":"What is a renewable resource?","answer":"A resource replenished on a relevant human timescale, provided use does not exceed renewal."},{"question":"What is a nonrenewable resource?","answer":"A resource that is finite or replenishes too slowly for ordinary human timescales."},{"question":"What does sustainability consider?","answer":"Meeting needs while considering long-term environmental, social, and economic effects."}]},{"id":"library-computer-science-algorithms-and-computational-thinking","subject":"Computer science","level":"Grades 5–8","title":"Algorithms and computational thinking","cards":[{"question":"What is an algorithm?","answer":"A well-defined sequence of steps for solving a problem or carrying out a task."},{"question":"What is decomposition?","answer":"Breaking a problem into smaller, manageable parts."},{"question":"What is a variable in a program?","answer":"A named reference or storage location used to work with a value, depending on the language."}]},{"id":"library-computer-science-programming-conditions-and-loops","subject":"Computer science","level":"Grades 9–12","title":"Programming: conditions and loops","cards":[{"question":"What does an if statement do?","answer":"Chooses whether to run code based on a condition."},{"question":"What does a loop do?","answer":"Repeats instructions according to a condition or iteration rule."},{"question":"What is an off-by-one error?","answer":"A boundary mistake that runs something one time too many or too few."}]},{"id":"library-computer-science-data-structures","subject":"Computer science","level":"Grades 9–12","title":"Data structures","cards":[{"question":"What is a list or array commonly used for?","answer":"Storing an ordered collection of elements."},{"question":"How does a stack behave?","answer":"Last in, first out."},{"question":"How does a queue behave?","answer":"First in, first out."}]},{"id":"library-computer-science-algorithms-and-complexity","subject":"Computer science","level":"College intro","title":"Algorithms and complexity","cards":[{"question":"What does Big O notation describe in algorithm analysis?","answer":"An upper bound on growth rate, commonly for time or space as input size increases."},{"question":"What is the worst-case time growth of ordinary linear search?","answer":"O(n)."},{"question":"What condition does binary search require?","answer":"An ordered search space where comparisons can eliminate half of the remaining candidates."}]},{"id":"library-computer-science-internet-and-digital-literacy","subject":"Computer science","level":"Grades 9–12","title":"Internet and digital literacy","cards":[{"question":"What is a URL?","answer":"A structured address identifying a resource and how to access it."},{"question":"What is phishing?","answer":"Deceptive communication intended to trick people into revealing information or taking harmful actions."},{"question":"Why check a website’s address before entering a password?","answer":"Lookalike sites can imitate trusted services. Verify the actual domain."}]},{"id":"library-computer-science-databases","subject":"Computer science","level":"College intro","title":"Databases","cards":[{"question":"What is a primary key?","answer":"A value or set of values that uniquely identifies a table row."},{"question":"What does SQL SELECT do?","answer":"Retrieves data matching a query."},{"question":"What is a foreign key?","answer":"A column or set of columns constrained to refer to a key in another or the same table."}]},{"id":"library-study-skills-starting-a-study-session","subject":"Study skills","level":"Grades 5–8","title":"Starting a study session","cards":[{"question":"What is one way to make a large assignment easier to start?","answer":"Choose a small, concrete next action, such as solving one problem or outlining one paragraph."},{"question":"Why choose a task before starting a timer?","answer":"A clear task helps direct attention during the session."},{"question":"What should you do when you get stuck on a step?","answer":"Identify the specific question, consult an example or trusted source, and ask for help when needed."}]},{"id":"library-study-skills-active-recall-and-spaced-practice","subject":"Study skills","level":"Grades 5–8","title":"Active recall and spaced practice","cards":[{"question":"What is active recall?","answer":"Trying to retrieve information from memory before checking the answer."},{"question":"What is spaced practice?","answer":"Returning to material across separate sessions instead of doing all practice at once."},{"question":"How should you use a flashcard you missed?","answer":"Read the explanation, connect it to what you know, and try recalling it again later."}]},{"id":"library-study-skills-planning-for-tests","subject":"Study skills","level":"Grades 9–12","title":"Planning for tests","cards":[{"question":"What should a test study plan begin with?","answer":"The tested topics, your available time, and the areas you find difficult."},{"question":"Why practice questions rather than only rereading?","answer":"They help you check what you can actually retrieve or apply."},{"question":"How can an error log help?","answer":"It records mistakes and their causes so you can target your next practice session."}]},{"id":"library-chinese-greetings","subject":"Chinese","level":"Language beginner","title":"Chinese: greetings and polite phrases","cards":[{"question":"What does 你好 (nǐ hǎo) mean?","answer":"Hello. Simplified: 你好. Traditional: 你好. Pinyin: nǐ hǎo."},{"question":"What does 谢谢 (xièxie) mean?","answer":"Thank you. Simplified: 谢谢. Traditional: 謝謝. Pinyin: xièxie."},{"question":"What does 再见 (zàijiàn) mean?","answer":"Goodbye. Simplified: 再见. Traditional: 再見. Pinyin: zàijiàn."},{"question":"What does 请 (qǐng) mean?","answer":"Please; to invite or request, depending on context. Simplified: 请. Traditional: 請. Pinyin: qǐng."},{"question":"What does 对不起 (duìbuqǐ) mean?","answer":"Sorry. Simplified: 对不起. Traditional: 對不起. Pinyin: duìbuqǐ."},{"question":"What does 早上好 (zǎoshang hǎo) mean?","answer":"Good morning. Simplified: 早上好. Traditional: 早上好. Pinyin: zǎoshang hǎo."}]},{"id":"library-chinese-numbers","subject":"Chinese","level":"Language beginner","title":"Chinese: numbers","cards":[{"question":"What does 零 (líng) mean?","answer":"Zero. Simplified: 零. Traditional: 零. Pinyin: líng."},{"question":"What does 一 (yī) mean?","answer":"One. Simplified: 一. Traditional: 一. Pinyin: yī."},{"question":"What does 二 (èr) mean?","answer":"Two. Simplified: 二. Traditional: 二. Pinyin: èr."},{"question":"What does 三 (sān) mean?","answer":"Three. Simplified: 三. Traditional: 三. Pinyin: sān."},{"question":"What does 四 (sì) mean?","answer":"Four. Simplified: 四. Traditional: 四. Pinyin: sì."},{"question":"What does 五 (wǔ) mean?","answer":"Five. Simplified: 五. Traditional: 五. Pinyin: wǔ."},{"question":"What does 六 (liù) mean?","answer":"Six. Simplified: 六. Traditional: 六. Pinyin: liù."},{"question":"What does 七 (qī) mean?","answer":"Seven. Simplified: 七. Traditional: 七. Pinyin: qī."},{"question":"What does 八 (bā) mean?","answer":"Eight. Simplified: 八. Traditional: 八. Pinyin: bā."},{"question":"What does 九 (jiǔ) mean?","answer":"Nine. Simplified: 九. Traditional: 九. Pinyin: jiǔ."},{"question":"What does 十 (shí) mean?","answer":"Ten. Simplified: 十. Traditional: 十. Pinyin: shí."},{"question":"What does 百 (bǎi) mean?","answer":"Hundred. Simplified: 百. Traditional: 百. Pinyin: bǎi."}]},{"id":"library-chinese-pronouns","subject":"Chinese","level":"Language beginner","title":"Chinese: personal pronouns","cards":[{"question":"What does 我 (wǒ) mean?","answer":"I; me. Simplified: 我. Traditional: 我. Pinyin: wǒ."},{"question":"What does 你 (nǐ) mean?","answer":"You, singular. Simplified: 你. Traditional: 你. Pinyin: nǐ."},{"question":"What does 他 (tā) mean?","answer":"He; him. Simplified: 他. Traditional: 他. Pinyin: tā."},{"question":"What does 她 (tā) mean?","answer":"She; her. Simplified: 她. Traditional: 她. Pinyin: tā."},{"question":"What does 我们 (wǒmen) mean?","answer":"We; us. Simplified: 我们. Traditional: 我們. Pinyin: wǒmen."},{"question":"What does 你们 (nǐmen) mean?","answer":"You, plural. Simplified: 你们. Traditional: 你們. Pinyin: nǐmen."}]},{"id":"library-chinese-family","subject":"Chinese","level":"Language beginner","title":"Chinese: family","cards":[{"question":"What does 妈妈 (māma) mean?","answer":"Mom. Simplified: 妈妈. Traditional: 媽媽. Pinyin: māma."},{"question":"What does 爸爸 (bàba) mean?","answer":"Dad. Simplified: 爸爸. Traditional: 爸爸. Pinyin: bàba."},{"question":"What does 哥哥 (gēge) mean?","answer":"Older brother. Simplified: 哥哥. Traditional: 哥哥. Pinyin: gēge."},{"question":"What does 姐姐 (jiějie) mean?","answer":"Older sister. Simplified: 姐姐. Traditional: 姐姐. Pinyin: jiějie."},{"question":"What does 弟弟 (dìdi) mean?","answer":"Younger brother. Simplified: 弟弟. Traditional: 弟弟. Pinyin: dìdi."},{"question":"What does 妹妹 (mèimei) mean?","answer":"Younger sister. Simplified: 妹妹. Traditional: 妹妹. Pinyin: mèimei."}]},{"id":"library-chinese-weekdays","subject":"Chinese","level":"Language beginner","title":"Chinese: days of the week","cards":[{"question":"What does 星期一 (xīngqīyī) mean?","answer":"Monday. Simplified: 星期一. Traditional: 星期一. Pinyin: xīngqīyī."},{"question":"What does 星期二 (xīngqīèr) mean?","answer":"Tuesday. Simplified: 星期二. Traditional: 星期二. Pinyin: xīngqīèr."},{"question":"What does 星期三 (xīngqīsān) mean?","answer":"Wednesday. Simplified: 星期三. Traditional: 星期三. Pinyin: xīngqīsān."},{"question":"What does 星期四 (xīngqīsì) mean?","answer":"Thursday. Simplified: 星期四. Traditional: 星期四. Pinyin: xīngqīsì."},{"question":"What does 星期五 (xīngqīwǔ) mean?","answer":"Friday. Simplified: 星期五. Traditional: 星期五. Pinyin: xīngqīwǔ."},{"question":"What does 星期六 (xīngqīliù) mean?","answer":"Saturday. Simplified: 星期六. Traditional: 星期六. Pinyin: xīngqīliù."},{"question":"What does 星期日 (xīngqīrì) mean?","answer":"Sunday; 星期天 (xīngqītiān) is also used. Simplified: 星期日. Traditional: 星期日. Pinyin: xīngqīrì."}]},{"id":"library-chinese-colors","subject":"Chinese","level":"Language beginner","title":"Chinese: colors","cards":[{"question":"What does 红色 (hóngsè) mean?","answer":"Red. Simplified: 红色. Traditional: 紅色. Pinyin: hóngsè."},{"question":"What does 蓝色 (lánsè) mean?","answer":"Blue. Simplified: 蓝色. Traditional: 藍色. Pinyin: lánsè."},{"question":"What does 绿色 (lǜsè) mean?","answer":"Green. Simplified: 绿色. Traditional: 綠色. Pinyin: lǜsè."},{"question":"What does 黄色 (huángsè) mean?","answer":"Yellow. Simplified: 黄色. Traditional: 黃色. Pinyin: huángsè."},{"question":"What does 白色 (báisè) mean?","answer":"White. Simplified: 白色. Traditional: 白色. Pinyin: báisè."},{"question":"What does 黑色 (hēisè) mean?","answer":"Black. Simplified: 黑色. Traditional: 黑色. Pinyin: hēisè."}]},{"id":"library-chinese-school","subject":"Chinese","level":"Language beginner","title":"Chinese: school and studying","cards":[{"question":"What does 学校 (xuéxiào) mean?","answer":"School. Simplified: 学校. Traditional: 學校. Pinyin: xuéxiào."},{"question":"What does 学生 (xuésheng) mean?","answer":"Student. Simplified: 学生. Traditional: 學生. Pinyin: xuésheng."},{"question":"What does 老师 (lǎoshī) mean?","answer":"Teacher. Simplified: 老师. Traditional: 老師. Pinyin: lǎoshī."},{"question":"What does 书 (shū) mean?","answer":"Book. Simplified: 书. Traditional: 書. Pinyin: shū."},{"question":"What does 笔 (bǐ) mean?","answer":"Pen or writing instrument. Simplified: 笔. Traditional: 筆. Pinyin: bǐ."},{"question":"What does 学习 (xuéxí) mean?","answer":"To study; to learn. Simplified: 学习. Traditional: 學習. Pinyin: xuéxí."}]},{"id":"library-chinese-questions","subject":"Chinese","level":"Language beginner","title":"Chinese: question words","cards":[{"question":"What does 什么 (shénme) mean?","answer":"What. Simplified: 什么. Traditional: 什麼. Pinyin: shénme."},{"question":"What does 谁 (shéi) mean?","answer":"Who; shuí is another pronunciation. Simplified: 谁. Traditional: 誰. Pinyin: shéi."},{"question":"What does 哪里 (nǎlǐ) mean?","answer":"Where. Simplified: 哪里. Traditional: 哪裡. Pinyin: nǎlǐ."},{"question":"What does 为什么 (wèishénme) mean?","answer":"Why. Simplified: 为什么. Traditional: 為什麼. Pinyin: wèishénme."},{"question":"What does 多少 (duōshǎo) mean?","answer":"How many; how much. Simplified: 多少. Traditional: 多少. Pinyin: duōshǎo."},{"question":"What does 怎么 (zěnme) mean?","answer":"How. Simplified: 怎么. Traditional: 怎麼. Pinyin: zěnme."}]},{"id":"library-chinese-pinyin","subject":"Chinese","level":"Language beginner","title":"Chinese: pinyin and tones","cards":[{"question":"What is Hanyu Pinyin?","answer":"A system using the Latin alphabet to represent Mandarin pronunciation; it is not a replacement for Chinese characters."},{"question":"How many main tones does standard Mandarin have?","answer":"Four main tones, plus a neutral tone."},{"question":"How are the four main tones marked on ma?","answer":"mā (high level), má (rising), mǎ (third tone, often low or dipping depending on context), mà (falling)."},{"question":"Do Simplified and Traditional Chinese scripts represent different spoken languages by themselves?","answer":"No. They are writing systems. These decks use Mandarin vocabulary and pinyin for both scripts."}]},{"id":"library-chinese-sentences","subject":"Chinese","level":"Language beginner","title":"Chinese: beginner sentence patterns","cards":[{"question":"What does 我学习中文 / 我學習中文 mean?","answer":"I study Chinese. Pinyin: Wǒ xuéxí Zhōngwén."},{"question":"How can 吗 / 嗎 turn many statements into yes–no questions?","answer":"Place it at the end: 你是学生吗？ / 你是學生嗎？ (Nǐ shì xuésheng ma?) means “Are you a student?”"},{"question":"How can 不 (bù) negate a simple statement using 是 (shì)?","answer":"Place 不 before 是: 我不是老师 / 我不是老師 means “I am not a teacher.” Spoken 不 before a fourth tone is commonly pronounced bú."},{"question":"What does 我喜欢学习 / 我喜歡學習 mean?","answer":"I like studying. Pinyin: Wǒ xǐhuan xuéxí."}]}];
